// Football Community Platform - High-Fidelity Screen Generator for Figma
// Generates 18 complete mobile screens (9 Light, 9 Dark) with Real Photos, Auto-Layout & Design Tokens

const IMAGES_B64 = {"venue1": "", "venue2": "", "venue3": "", "game1": "", "event1": "", "event2": "", "event3": "", "event4": ""};

async function run() {
  figma.notify("Generating high-fidelity Football Community screens with real photos...");

  // Load fonts safely
  try {
    await figma.loadFontAsync({ family: "Inter", style: "Regular" });
    await figma.loadFontAsync({ family: "Inter", style: "Medium" });
    await figma.loadFontAsync({ family: "Inter", style: "Semi Bold" });
    await figma.loadFontAsync({ family: "Inter", style: "Bold" });
  } catch (e) {
    try {
      await figma.loadFontAsync({ family: "Roboto", style: "Regular" });
      await figma.loadFontAsync({ family: "Roboto", style: "Medium" });
      await figma.loadFontAsync({ family: "Roboto", style: "Bold" });
    } catch (e2) {
      console.log("Font fallback to default");
    }
  }

  const FONT_REG = { family: "Inter", style: "Regular" };
  const FONT_MED = { family: "Inter", style: "Medium" };
  const FONT_SB = { family: "Inter", style: "Semi Bold" };
  const FONT_B = { family: "Inter", style: "Bold" };

  // Helper: Hex to Figma RGB (0-1)
  function hex(h, alpha = 1) {
    h = h.replace("#", "");
    const r = parseInt(h.substring(0, 2), 16) / 255;
    const g = parseInt(h.substring(2, 4), 16) / 255;
    const b = parseInt(h.substring(4, 6), 16) / 255;
    return [{ type: "SOLID", color: { r, g, b }, opacity: alpha }];
  }

  // Cache for Figma image hashes
  const imageHashCache = {};
  function getImageFill(name) {
    if (!IMAGES_B64[name]) return hex("#123D2B");
    if (imageHashCache[name]) {
      return { type: "IMAGE", scaleMode: "FILL", imageHash: imageHashCache[name] };
    }
    try {
      const b64 = IMAGES_B64[name];
      const binaryString = atob(b64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      const img = figma.createImage(bytes);
      imageHashCache[name] = img.hash;
      return { type: "IMAGE", scaleMode: "FILL", imageHash: img.hash };
    } catch (err) {
      console.log("Error creating image fill: " + err);
      return hex("#123D2B");
    }
  }

  // Tokens
  const LightTokens = {
    bg: hex("#F4F4F4"),
    surface: hex("#FFFFFF"),
    surfaceMuted: hex("#E9F5EC"),
    primary: hex("#123D2B"),
    primaryHover: hex("#26734D"),
    accent: hex("#B8F34A"),
    accentHover: hex("#A6DF3E"),
    textPrimary: hex("#17211B"),
    textSecondary: hex("#455149"),
    textMuted: hex("#87928A"),
    border: hex("#E5EAE5"),
    success: hex("#16834A"),
    warning: hex("#D98B16"),
    error: hex("#D94343"),
    info: hex("#2878C7"),
    heroCard: hex("#123D2B"),
    heroText: hex("#FFFFFF"),
    navBg: hex("#FFFFFF", 0.96),
    navBorder: hex("#E5EAE5")
  };

  const DarkTokens = {
    bg: hex("#0C130F"),
    surface: hex("#15201A"),
    surfaceMuted: hex("#1F2D25"),
    primary: hex("#123D2B"),
    primaryHover: hex("#26734D"),
    accent: hex("#B8F34A"),
    accentHover: hex("#A6DF3E"),
    textPrimary: hex("#F1F6F2"),
    textSecondary: hex("#B5C2BA"),
    textMuted: hex("#8FA096"),
    border: hex("#263329"),
    success: hex("#4CD08A"),
    warning: hex("#EDA83A"),
    error: hex("#FF7070"),
    info: hex("#5BA6EB"),
    heroCard: hex("#15201A"),
    heroText: hex("#F1F6F2"),
    navBg: hex("#15201A", 0.96),
    navBorder: hex("#263329")
  };

  // Helper: Text with Auto Layout support
  function createText(chars, size, font, color, stretch = false) {
    const t = figma.createText();
    t.fontName = font;
    t.fontSize = size;
    t.characters = chars;
    t.fills = color;
    if (stretch) {
      t.layoutAlign = "STRETCH";
      t.textAutoResize = "HEIGHT";
    } else {
      t.textAutoResize = "WIDTH_AND_HEIGHT";
    }
    return t;
  }

  // Helper: Create Auto-Layout Frame
  function createAutoFrame(name, layoutMode, spacing, padX, padY, bg = null, radius = 0) {
    const f = figma.createFrame();
    f.name = name;
    f.layoutMode = layoutMode;
    f.itemSpacing = spacing;
    f.paddingLeft = padX;
    f.paddingRight = padX;
    f.paddingTop = padY;
    f.paddingBottom = padY;
    f.cornerRadius = radius;
    if (bg) f.fills = bg;
    else f.fills = [];
    return f;
  }

  // Helper: Pill Button (Fixed width or fit contents)
  function createButton(text, bg, textColor, isFullWidth = true) {
    const btn = createAutoFrame("Button", "HORIZONTAL", 8, 18, 14, bg, 999);
    btn.primaryAxisAlignItems = "CENTER";
    btn.counterAxisAlignItems = "CENTER";
    const label = createText(text, 14, FONT_B, textColor, false);
    btn.appendChild(label);
    if (isFullWidth) {
      btn.layoutAlign = "STRETCH";
      btn.primaryAxisSizingMode = "FIXED";
    } else {
      btn.layoutAlign = "INHERIT";
      btn.primaryAxisSizingMode = "AUTO";
      btn.counterAxisSizingMode = "AUTO";
      btn.paddingTop = 10;
      btn.paddingBottom = 10;
      btn.paddingLeft = 16;
      btn.paddingRight = 16;
    }
    return btn;
  }

  // Helper: Badge / Tag
  function createTag(text, bg, textColor) {
    const tag = createAutoFrame("Tag", "HORIZONTAL", 4, 10, 5, bg, 999);
    tag.primaryAxisAlignItems = "CENTER";
    tag.counterAxisAlignItems = "CENTER";
    tag.primaryAxisSizingMode = "AUTO";
    tag.counterAxisSizingMode = "AUTO";
    const t = createText(text, 11, FONT_B, textColor, false);
    tag.appendChild(t);
    return tag;
  }

  // Helper: Card Image Box
  function createCardImage(imageName, height = 140, radius = 14) {
    const rect = figma.createRectangle();
    rect.name = "CoverImage_" + imageName;
    rect.layoutAlign = "STRETCH";
    rect.resize(322, height);
    rect.cornerRadius = radius;
    rect.fills = [getImageFill(imageName)];
    return rect;
  }

  // Helper: Bottom Pill Floating Nav
  function createBottomNav(T, activeTab = "Home") {
    const navWrapper = createAutoFrame("NavWrapper", "HORIZONTAL", 0, 20, 16, null, 0);
    navWrapper.layoutAlign = "STRETCH";
    navWrapper.primaryAxisAlignItems = "CENTER";
    navWrapper.counterAxisAlignItems = "CENTER";

    const nav = createAutoFrame("BottomNav", "HORIZONTAL", 8, 10, 8, T.navBg, 999);
    nav.strokes = T.border;
    nav.strokeWeight = 1;
    nav.primaryAxisAlignItems = "SPACE_BETWEEN";
    nav.counterAxisAlignItems = "CENTER";
    nav.resize(350, 56);
    nav.primaryAxisSizingMode = "FIXED";

    const tabs = [
      { id: "Home", label: "Home", icon: "⚽" },
      { id: "Explore", label: "Explore", icon: "🔍" },
      { id: "Community", label: "Teams", icon: "👥" },
      { id: "Activity", label: "Activity", icon: "📅" },
      { id: "Profile", label: "Profile", icon: "👤" }
    ];

    for (const item of tabs) {
      const isActive = item.id === activeTab;
      const tabFrame = createAutoFrame(item.id, "HORIZONTAL", 6, 12, 8, isActive ? T.accent : [], 999);
      tabFrame.primaryAxisAlignItems = "CENTER";
      tabFrame.counterAxisAlignItems = "CENTER";
      tabFrame.primaryAxisSizingMode = "AUTO";
      tabFrame.counterAxisSizingMode = "AUTO";

      const ico = createText(item.icon, 12, FONT_REG, isActive ? hex("#123D2B") : T.textMuted);
      tabFrame.appendChild(ico);
      if (isActive) {
        const lbl = createText(item.label, 11, FONT_B, hex("#123D2B"));
        tabFrame.appendChild(lbl);
      }
      nav.appendChild(tabFrame);
    }
    navWrapper.appendChild(nav);
    return navWrapper;
  }

  // Base Phone Shell (Auto-Layout from top to bottom)
  function createPhone(name, T, x, y) {
    const phone = createAutoFrame(name, "VERTICAL", 0, 0, 0, T.bg, 46);
    phone.resize(390, 844);
    phone.primaryAxisSizingMode = "FIXED";
    phone.counterAxisSizingMode = "FIXED";
    phone.x = x;
    phone.y = y;
    phone.clipsContent = true;

    // Top Status Bar (Height 44)
    const status = createAutoFrame("StatusBar", "HORIZONTAL", 0, 26, 14, null, 0);
    status.layoutAlign = "STRETCH";
    status.primaryAxisAlignItems = "SPACE_BETWEEN";
    status.counterAxisAlignItems = "CENTER";
    status.resize(390, 44);
    status.primaryAxisSizingMode = "FIXED";

    const time = createText("9:41", 14, FONT_SB, T.textPrimary);
    const icons = createText("●●● 5G ▮", 12, FONT_REG, T.textMuted);
    status.appendChild(time);
    status.appendChild(icons);
    phone.appendChild(status);

    return phone;
  }

  // Content Area Builder (Scrollable container inside phone)
  function createContentArea() {
    const body = createAutoFrame("BodyContent", "VERTICAL", 14, 20, 10, null, 0);
    body.layoutAlign = "STRETCH";
    body.layoutGrow = 1;
    body.clipsContent = true;
    return body;
  }

  // Standard Card Builder
  function createCard(T, spacing = 10, pad = 14) {
    const c = createAutoFrame("Card", "VERTICAL", spacing, pad, pad, T.surface, 16);
    c.layoutAlign = "STRETCH";
    c.strokes = T.border;
    c.strokeWeight = 1;
    return c;
  }

  // Row with Space Between
  function createSpRow() {
    const r = createAutoFrame("Row", "HORIZONTAL", 10, 0, 0, null, 0);
    r.layoutAlign = "STRETCH";
    r.primaryAxisAlignItems = "SPACE_BETWEEN";
    r.counterAxisAlignItems = "CENTER";
    return r;
  }

  // ==========================================
  // 9 SCREENS (LIGHT & DARK)
  // ==========================================

  // 1. WELCOME SCREEN
  function buildWelcome(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 01 Welcome" : "Light - 01 Welcome", T, x, y);

    const welcomeBody = createAutoFrame("WelcomeBody", "VERTICAL", 16, 24, 34, null, 0);
    welcomeBody.layoutAlign = "STRETCH";
    welcomeBody.layoutGrow = 1;
    welcomeBody.primaryAxisAlignItems = "MAX"; // push to bottom

    // Big hero photo card
    const heroPhoto = createCardImage("game1", 420, 24);
    heroPhoto.layoutAlign = "STRETCH";
    welcomeBody.appendChild(heroPhoto);

    welcomeBody.appendChild(createTag("LAGOS, NIGERIA", T.accent, hex("#123D2B")));
    welcomeBody.appendChild(createText("The home of football communities", 28, FONT_B, T.textPrimary, true));
    welcomeBody.appendChild(createText("Find pitches to play, open games to join, and grassroots competitions to watch.", 14, FONT_REG, T.textSecondary, true));

    welcomeBody.appendChild(createButton("Get Started", T.primary, hex("#FFFFFF"), true));
    welcomeBody.appendChild(createButton("I already have an account", T.surface, T.textPrimary, true));

    phone.appendChild(welcomeBody);
    return phone;
  }

  // 2. HOME SCREEN
  function buildHome(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 02 Home" : "Light - 02 Home", T, x, y);
    const body = createContentArea();

    // Top greeting row
    const topRow = createSpRow();
    const userCol = createAutoFrame("UserCol", "VERTICAL", 2, 0, 0, null, 0);
    userCol.appendChild(createText("Welcome back 👋", 12, FONT_REG, T.textMuted));
    userCol.appendChild(createText("Tunde Adeyemi (Lekki Phase 1)", 15, FONT_B, T.textPrimary));
    topRow.appendChild(userCol);

    const bell = createAutoFrame("Bell", "HORIZONTAL", 0, 10, 10, T.surface, 999);
    bell.strokes = T.border;
    bell.strokeWeight = 1;
    bell.appendChild(createText("🔔", 14, FONT_REG, T.textPrimary));
    topRow.appendChild(bell);
    body.appendChild(topRow);

    // Search bar
    const search = createAutoFrame("SearchBar", "HORIZONTAL", 10, 16, 12, T.surface, 999);
    search.layoutAlign = "STRETCH";
    search.strokes = T.border;
    search.strokeWeight = 1;
    search.appendChild(createText("🔍 Search pitches, games, tournaments...", 13, FONT_REG, T.textMuted));
    body.appendChild(search);

    // Featured Match Hero Card (Thursday Night 5s with photo)
    const heroCard = createAutoFrame("HeroCard", "VERTICAL", 12, 14, 14, T.heroCard, 18);
    heroCard.layoutAlign = "STRETCH";

    const heroImg = createCardImage("game1", 120, 12);
    heroCard.appendChild(heroImg);

    const heroTop = createSpRow();
    heroTop.appendChild(createTag("OPEN GAME · 2 SLOTS LEFT", T.accent, hex("#123D2B")));
    heroTop.appendChild(createText("₦2,500 / player", 13, FONT_B, hex("#FFFFFF")));
    heroCard.appendChild(heroTop);

    heroCard.appendChild(createText("Thursday Night 5-a-Side", 18, FONT_B, hex("#FFFFFF"), true));
    heroCard.appendChild(createText("Lekki Goal Arena · Thu 12 Nov · 20:00 – 21:00", 12, FONT_REG, hex("#E9F5EC"), true));

    const joinBtn = createButton("Reserve Slot", T.accent, hex("#123D2B"), true);
    heroCard.appendChild(joinBtn);
    body.appendChild(heroCard);

    // Section: Nearby Football Pitches
    const secRow = createSpRow();
    secRow.appendChild(createText("Nearby Football Pitches", 16, FONT_B, T.textPrimary));
    secRow.appendChild(createText("See all", 12, FONT_SB, T.primary));
    body.appendChild(secRow);

    // Pitch Card with photo
    const pCard = createCard(T, 10, 12);
    pCard.appendChild(createCardImage("venue1", 120, 12));

    const pTitleRow = createSpRow();
    pTitleRow.appendChild(createText("Lekki Goal Arena", 16, FONT_B, T.textPrimary));
    pTitleRow.appendChild(createTag("⭐ 4.7 (128)", T.surfaceMuted, T.success));
    pCard.appendChild(pTitleRow);

    const pBtm = createSpRow();
    pBtm.appendChild(createText("5-a-side · 7-a-side (2.1 km away)", 12, FONT_REG, T.textSecondary));
    pBtm.appendChild(createText("From ₦25,000/hr", 14, FONT_B, T.primary));
    pCard.appendChild(pBtm);
    body.appendChild(pCard);

    phone.appendChild(body);
    phone.appendChild(createBottomNav(T, "Home"));
    return phone;
  }

  // 3. EXPLORE SCREEN
  function buildExplore(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 03 Explore" : "Light - 03 Explore", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("Explore Football", 22, FONT_B, T.textPrimary));

    // Category Tabs (Pill style)
    const tabRow = createAutoFrame("TabRow", "HORIZONTAL", 8, 0, 0, null, 0);
    tabRow.appendChild(createTag("Pitches", T.primary, hex("#FFFFFF")));
    tabRow.appendChild(createTag("Open Games", T.surface, T.textMuted));
    tabRow.appendChild(createTag("Matches", T.surface, T.textMuted));
    tabRow.appendChild(createTag("Competitions", T.surface, T.textMuted));
    body.appendChild(tabRow);

    // Format Filters
    const formatRow = createAutoFrame("FormatRow", "HORIZONTAL", 8, 0, 0, null, 0);
    formatRow.appendChild(createTag("All Formats", T.accent, hex("#123D2B")));
    formatRow.appendChild(createTag("5-a-side", T.surface, T.textSecondary));
    formatRow.appendChild(createTag("7-a-side", T.surface, T.textSecondary));
    formatRow.appendChild(createTag("11-a-side", T.surface, T.textSecondary));
    body.appendChild(formatRow);

    // Venue 1 Card (Yaba Turf Club with photo)
    const c1 = createCard(T, 10, 12);
    c1.appendChild(createCardImage("venue2", 130, 12));
    const c1Top = createSpRow();
    c1Top.appendChild(createText("Yaba Turf Club", 16, FONT_B, T.textPrimary));
    c1Top.appendChild(createTag("🛡️ Verified", T.surfaceMuted, T.success));
    c1.appendChild(c1Top);
    c1.appendChild(createText("📍 Yaba, Lagos · 4.8 km · Floodlights & Parking", 12, FONT_REG, T.textSecondary));
    const c1Price = createSpRow();
    c1Price.appendChild(createText("2 Pitches (5-a-side)", 12, FONT_SB, T.textMuted));
    c1Price.appendChild(createText("₦18,000 / hr", 14, FONT_B, T.primary));
    c1.appendChild(c1Price);
    body.appendChild(c1);

    // Venue 2 Card (Ikeja Sports Ground with photo)
    const c2 = createCard(T, 10, 12);
    c2.appendChild(createCardImage("venue3", 130, 12));
    const c2Top = createSpRow();
    c2Top.appendChild(createText("Ikeja Sports Ground", 16, FONT_B, T.textPrimary));
    c2Top.appendChild(createTag("⭐ 4.2", T.surfaceMuted, T.textSecondary));
    c2.appendChild(c2Top);
    c2.appendChild(createText("📍 Ikeja GRA · 7.3 km · Grandstands & Natural Grass", 12, FONT_REG, T.textSecondary));
    const c2Price = createSpRow();
    c2Price.appendChild(createText("11-a-side & 7-a-side", 12, FONT_SB, T.textMuted));
    c2Price.appendChild(createText("₦30,000 / hr", 14, FONT_B, T.primary));
    c2.appendChild(c2Price);
    body.appendChild(c2);

    phone.appendChild(body);
    phone.appendChild(createBottomNav(T, "Explore"));
    return phone;
  }

  // 4. VENUE DETAILS & PITCH SELECTION
  function buildVenueDetail(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 04 Venue Detail" : "Light - 04 Venue Detail", T, x, y);
    const body = createContentArea();

    // Back nav
    const backRow = createSpRow();
    backRow.appendChild(createText("← Back to Pitches", 13, FONT_SB, T.primary));
    backRow.appendChild(createText("Share 🔗", 13, FONT_REG, T.textMuted));
    body.appendChild(backRow);

    // Big Photo
    body.appendChild(createCardImage("venue1", 160, 16));

    // Title & info
    body.appendChild(createText("Lekki Goal Arena", 22, FONT_B, T.textPrimary, true));
    body.appendChild(createText("📍 Plot 12, Admiralty Way, Lekki Phase 1, Lagos | Open daily 07:00 – 23:00 · ⭐ 4.7 (128 reviews)", 12, FONT_REG, T.textSecondary, true));

    // Pitch Selection
    body.appendChild(createText("Select Playing Pitch", 15, FONT_B, T.textPrimary));
    const pitchA = createAutoFrame("PitchA", "VERTICAL", 6, 14, 12, T.surfaceMuted, 14);
    pitchA.layoutAlign = "STRETCH";
    pitchA.strokes = T.primary;
    pitchA.strokeWeight = 2;
    pitchA.appendChild(createText("✓ Pitch A · 5-a-Side (Selected)", 14, FONT_B, T.primary));
    pitchA.appendChild(createText("Astro turf, floodlights & match netting · ₦25,000/hr", 12, FONT_REG, T.textSecondary));
    body.appendChild(pitchA);

    // Time Slot Selector
    body.appendChild(createText("Choose Slot (Thu 12 Nov)", 15, FONT_B, T.textPrimary));
    const slotGrid = createAutoFrame("SlotGrid", "HORIZONTAL", 8, 0, 0, null, 0);
    slotGrid.appendChild(createTag("18:00", T.surface, T.textSecondary));
    slotGrid.appendChild(createTag("19:00", T.surface, T.textSecondary));
    slotGrid.appendChild(createTag("20:00 (Selected)", T.accent, hex("#123D2B")));
    slotGrid.appendChild(createTag("21:00", T.surface, T.textSecondary));
    body.appendChild(slotGrid);

    // Sticky Bottom Action Bar
    const btmBar = createCard(T, 8, 12);
    const btmRow = createSpRow();
    const btmCol = createAutoFrame("BtmCol", "VERTICAL", 2, 0, 0, null, 0);
    btmCol.appendChild(createText("Total (1 hour)", 11, FONT_REG, T.textMuted));
    btmCol.appendChild(createText("₦25,000", 18, FONT_B, T.textPrimary));
    btmRow.appendChild(btmCol);

    btmRow.appendChild(createButton("Book Pitch", T.primary, hex("#FFFFFF"), false));
    btmBar.appendChild(btmRow);
    body.appendChild(btmBar);

    phone.appendChild(body);
    return phone;
  }

  // 5. BOOKING REVIEW & SLOT HOLD
  function buildBookingReview(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 05 Slot Hold & Pay" : "Light - 05 Slot Hold & Pay", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("← Review & Payment", 16, FONT_B, T.textPrimary));

    // Timer Banner (PRD §6.1.3: temporary slot hold)
    const holdBanner = createAutoFrame("HoldBanner", "HORIZONTAL", 10, 14, 12, T.heroCard, 14);
    holdBanner.layoutAlign = "STRETCH";
    holdBanner.primaryAxisAlignItems = "SPACE_BETWEEN";
    holdBanner.counterAxisAlignItems = "CENTER";
    holdBanner.appendChild(createText("⏱️ Pitch Slot Held", 13, FONT_B, hex("#FFFFFF")));
    holdBanner.appendChild(createTag("09:42 remaining", T.accent, hex("#123D2B")));
    body.appendChild(holdBanner);

    // Summary Card
    const sumCard = createCard(T, 10, 14);
    sumCard.appendChild(createText("Lekki Goal Arena · Pitch A", 16, FONT_B, T.textPrimary));
    sumCard.appendChild(createText("Date: Thursday, 12 Nov 2026 | Time: 20:00 – 21:00 (1 hr) | Ref: FCP-482913", 12, FONT_REG, T.textSecondary, true));
    body.appendChild(sumCard);

    // Payment Option Radio (PRD §6.1.5)
    body.appendChild(createText("Payment Option", 15, FONT_B, T.textPrimary));

    // Full Payment
    const optFull = createAutoFrame("OptFull", "VERTICAL", 6, 14, 12, T.surfaceMuted, 14);
    optFull.layoutAlign = "STRETCH";
    optFull.strokes = T.primary;
    optFull.strokeWeight = 2;
    optFull.appendChild(createText("● Option A: Pay in Full (Selected)", 14, FONT_B, T.primary));
    optFull.appendChild(createText("Pay entire ₦25,000 online now for instant confirmed booking.", 12, FONT_REG, T.textSecondary));
    body.appendChild(optFull);

    // Deposit Option
    const optDep = createAutoFrame("OptDep", "VERTICAL", 6, 14, 12, T.surface, 14);
    optDep.layoutAlign = "STRETCH";
    optDep.strokes = T.border;
    optDep.strokeWeight = 1;
    optDep.appendChild(createText("○ Option B: Pay 30% Deposit (₦7,500)", 14, FONT_B, T.textPrimary));
    optDep.appendChild(createText("Pay balance of ₦17,500 at venue prior to kickoff.", 12, FONT_REG, T.textMuted));
    body.appendChild(optDep);

    body.appendChild(createText("Cancellation Policy: Free cancellation up to 24 hours prior. Non-refundable within 6 hours.", 11, FONT_REG, T.textMuted, true));
    body.appendChild(createButton("Pay ₦25,000 NGN Now", T.accent, hex("#123D2B"), true));

    phone.appendChild(body);
    return phone;
  }

  // 6. OPEN GAME DETAILS (SLOT BOOKING)
  function buildOpenGame(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 06 Open Game" : "Light - 06 Open Game", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("← Open Match Details", 16, FONT_B, T.textPrimary));

    // Hero Match Card with photo
    const matchCard = createAutoFrame("MatchHero", "VERTICAL", 10, 14, 14, T.heroCard, 18);
    matchCard.layoutAlign = "STRETCH";
    matchCard.appendChild(createCardImage("game1", 130, 12));

    const mTop = createSpRow();
    mTop.appendChild(createTag("5-A-SIDE RECREATIONAL", T.accent, hex("#123D2B")));
    mTop.appendChild(createText("₦2,500 / player", 14, FONT_B, hex("#FFFFFF")));
    matchCard.appendChild(mTop);

    matchCard.appendChild(createText("Thursday Night 5s", 20, FONT_B, hex("#FFFFFF")));
    matchCard.appendChild(createText("Organised by Captain Tunde Adeyemi | Lekki Goal Arena · Thu 12 Nov · 20:00", 12, FONT_REG, hex("#E9F5EC"), true));
    body.appendChild(matchCard);

    // Player Slots Progress (PRD §6.1.4: 8 of 10 filled)
    const slotCard = createCard(T, 10, 14);
    const slotHeader = createSpRow();
    slotHeader.appendChild(createText("Player Slots: 8 of 10 Joined", 14, FONT_B, T.textPrimary));
    slotHeader.appendChild(createTag("2 Slots Left", T.warning, hex("#FFFFFF")));
    slotCard.appendChild(slotHeader);

    // Visual Progress Bar
    const pBar = createAutoFrame("PBar", "HORIZONTAL", 0, 0, 0, T.surfaceMuted, 999);
    pBar.layoutAlign = "STRETCH";
    pBar.resize(322, 8);
    const pFill = createAutoFrame("Fill", "HORIZONTAL", 0, 0, 0, T.success, 999);
    pFill.resize(256, 8);
    pBar.appendChild(pFill);
    slotCard.appendChild(pBar);

    slotCard.appendChild(createText("Confirmed: Tunde, Emeka, Chidi, Sadiq, Femi, Kunle, Ayo, Babatunde", 11, FONT_REG, T.textMuted, true));
    body.appendChild(slotCard);

    // Contribution info
    const infoCard = createCard(T, 6, 12);
    infoCard.appendChild(createText("What your contribution covers:", 13, FONT_B, T.textPrimary));
    infoCard.appendChild(createText("1-hour turf booking, floodlights, official match bibs and clean water.", 12, FONT_REG, T.textSecondary, true));
    body.appendChild(infoCard);

    body.appendChild(createButton("Join Game · Pay ₦2,500", T.primary, hex("#FFFFFF"), true));

    phone.appendChild(body);
    return phone;
  }

  // 7. WATCH - MATCH CENTRE
  function buildWatch(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 07 Match Centre" : "Light - 07 Match Centre", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("WATCH · Match Centre", 20, FONT_B, T.textPrimary));

    // Live Scoreboard Card
    const liveCard = createAutoFrame("LiveCard", "VERTICAL", 12, 16, 16, T.heroCard, 20);
    liveCard.layoutAlign = "STRETCH";

    const liveTop = createSpRow();
    liveTop.appendChild(createText("Lagos Grassroots Cup Final", 13, FONT_REG, hex("#E9F5EC")));
    liveTop.appendChild(createTag("🔴 LIVE · 54'", T.error, hex("#FFFFFF")));
    liveCard.appendChild(liveTop);

    // Teams Score Row
    const scoreRow = createSpRow();
    const t1 = createAutoFrame("T1", "VERTICAL", 4, 0, 0, null, 0);
    t1.appendChild(createText("Lekki Lions", 16, FONT_B, hex("#FFFFFF")));
    t1.appendChild(createText("Home", 11, FONT_REG, hex("#E9F5EC")));
    scoreRow.appendChild(t1);

    scoreRow.appendChild(createText("1 : 1", 32, FONT_B, T.accent));

    const t2 = createAutoFrame("T2", "VERTICAL", 4, 0, 0, null, 0);
    t2.primaryAxisAlignItems = "MAX";
    t2.appendChild(createText("Yaba Rovers", 16, FONT_B, hex("#FFFFFF")));
    t2.appendChild(createText("Away", 11, FONT_REG, hex("#E9F5EC")));
    scoreRow.appendChild(t2);
    liveCard.appendChild(scoreRow);

    liveCard.appendChild(createText("📍 Teslim Balogun Stadium, Surulere", 12, FONT_REG, hex("#E9F5EC")));
    body.appendChild(liveCard);

    // Match Photo Banner
    body.appendChild(createCardImage("event1", 130, 14));

    // Official Timeline
    body.appendChild(createText("Match Timeline & Events", 15, FONT_B, T.textPrimary));
    const events = [
      { min: "54'", txt: "Substitution: #10 Sadiq in for Lekki Lions" },
      { min: "31'", txt: "⚽ GOAL! Yaba Rovers equalises (Femi K.)" },
      { min: "12'", txt: "⚽ GOAL! Lekki Lions opens scoring (Emeka O.)" }
    ];
    for (const ev of events) {
      const r = createAutoFrame("EvRow", "HORIZONTAL", 10, 12, 10, T.surface, 12);
      r.layoutAlign = "STRETCH";
      r.strokes = T.border;
      r.strokeWeight = 1;
      r.appendChild(createTag(ev.min, T.surfaceMuted, T.primary));
      r.appendChild(createText(ev.txt, 12, FONT_REG, T.textPrimary));
      body.appendChild(r);
    }

    phone.appendChild(body);
    phone.appendChild(createBottomNav(T, "Explore"));
    return phone;
  }

  // 8. TEAM PROFILE (CONNECT)
  function buildTeam(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 08 Team Profile" : "Light - 08 Team Profile", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("← Community & Teams", 16, FONT_B, T.textPrimary));

    // Team Hero Banner
    const tHeader = createAutoFrame("THeader", "VERTICAL", 10, 16, 16, T.heroCard, 20);
    tHeader.layoutAlign = "STRETCH";
    tHeader.appendChild(createTag("COMMUNITY CLUB", T.accent, hex("#123D2B")));
    tHeader.appendChild(createText("Lekki Lions FC", 24, FONT_B, hex("#FFFFFF")));
    tHeader.appendChild(createText("📍 Lekki, Lagos · 7-a-side & 11-a-side | Squad: 14 Active Players · Founded 2024", 12, FONT_REG, hex("#E9F5EC"), true));

    const btnRow = createAutoFrame("BtnRow", "HORIZONTAL", 8, 0, 0, null, 0);
    btnRow.appendChild(createButton("Follow Club", T.accent, hex("#123D2B"), false));
    btnRow.appendChild(createButton("Request to Join", hex("#FFFFFF", 0.15), hex("#FFFFFF"), false));
    tHeader.appendChild(btnRow);
    body.appendChild(tHeader);

    // Team photo
    body.appendChild(createCardImage("event2", 120, 14));

    // Squad Roster
    body.appendChild(createText("Squad Roster (14)", 15, FONT_B, T.textPrimary));
    const players = [
      { name: "Tunde Adeyemi", role: "Captain", pos: "Midfield" },
      { name: "Emeka Obi", role: "Vice Captain", pos: "Forward" },
      { name: "Ayo Bello", role: "Player", pos: "Goalkeeper" }
    ];
    for (const p of players) {
      const pRow = createSpRow();
      pRow.paddingTop = 8;
      pRow.paddingBottom = 8;
      pRow.paddingLeft = 12;
      pRow.paddingRight = 12;
      pRow.cornerRadius = 12;
      pRow.fills = T.surface;
      pRow.strokes = T.border;
      pRow.strokeWeight = 1;

      const pLeft = createAutoFrame("PLeft", "VERTICAL", 2, 0, 0, null, 0);
      pLeft.appendChild(createText(p.name, 14, FONT_B, T.textPrimary));
      pLeft.appendChild(createText(p.pos, 11, FONT_REG, T.textMuted));
      pRow.appendChild(pLeft);

      pRow.appendChild(createTag(p.role, T.surfaceMuted, T.primary));
      body.appendChild(pRow);
    }

    phone.appendChild(body);
    phone.appendChild(createBottomNav(T, "Community"));
    return phone;
  }

  // 9. MY ACTIVITY & QR TICKETS
  function buildActivity(T, x, y, isDark) {
    const phone = createPhone(isDark ? "Dark - 09 My Activity" : "Light - 09 My Activity", T, x, y);
    const body = createContentArea();

    body.appendChild(createText("My Football Activity", 22, FONT_B, T.textPrimary));

    // Tabs
    const aTabs = createAutoFrame("ATabs", "HORIZONTAL", 8, 0, 0, null, 0);
    aTabs.appendChild(createTag("Pitch Bookings", T.surface, T.textMuted));
    aTabs.appendChild(createTag("Games Joined", T.surface, T.textMuted));
    aTabs.appendChild(createTag("Match Tickets (1)", T.primary, hex("#FFFFFF")));
    body.appendChild(aTabs);

    // Digital Match Ticket Card
    const ticketCard = createAutoFrame("TicketCard", "VERTICAL", 12, 16, 16, T.heroCard, 20);
    ticketCard.layoutAlign = "STRETCH";
    ticketCard.primaryAxisAlignItems = "CENTER";
    ticketCard.counterAxisAlignItems = "CENTER";

    ticketCard.appendChild(createTag("ADMIT ONE · GENERAL ENCLOSURE", T.accent, hex("#123D2B")));
    ticketCard.appendChild(createText("Lagos Grassroots Cup Final", 18, FONT_B, hex("#FFFFFF")));
    ticketCard.appendChild(createText("Sat 14 Nov 2026 · 15:00 Kickoff | Teslim Balogun Stadium, Surulere", 12, FONT_REG, hex("#E9F5EC"), true));

    // QR Code Frame
    const qrFrame = createAutoFrame("QRFrame", "VERTICAL", 6, 16, 16, hex("#FFFFFF"), 14);
    qrFrame.resize(130, 130);
    qrFrame.primaryAxisAlignItems = "CENTER";
    qrFrame.counterAxisAlignItems = "CENTER";
    qrFrame.appendChild(createText("⬛⬛ 🔲 ⬛⬛", 18, FONT_B, hex("#000000")));
    ticketCard.appendChild(qrFrame);

    ticketCard.appendChild(createText("Scan at Stadium Turnstiles · Ref #TIC-88392", 11, FONT_REG, hex("#E9F5EC")));
    body.appendChild(ticketCard);

    // Booking Card below ticket
    const bCard = createCard(T, 8, 12);
    const bTop = createSpRow();
    bTop.appendChild(createText("Thursday 5-a-Side", 14, FONT_B, T.textPrimary));
    bTop.appendChild(createTag("Confirmed", T.surfaceMuted, T.success));
    bCard.appendChild(bTop);
    bCard.appendChild(createText("Lekki Goal Arena · Thu 12 Nov · 20:00 · ₦25,000 NGN Paid", 12, FONT_REG, T.textSecondary, true));
    body.appendChild(bCard);

    phone.appendChild(body);
    phone.appendChild(createBottomNav(T, "Activity"));
    return phone;
  }

  // ==========================================
  // CANVAS PLACEMENT
  // ==========================================
  const startX = 0;
  const startY = 0;
  const spacingX = 430;
  const spacingY = 920;

  // Row 1: Light Theme Screens (9 screens)
  buildWelcome(LightTokens, startX + 0 * spacingX, startY, false);
  buildHome(LightTokens, startX + 1 * spacingX, startY, false);
  buildExplore(LightTokens, startX + 2 * spacingX, startY, false);
  buildVenueDetail(LightTokens, startX + 3 * spacingX, startY, false);
  buildBookingReview(LightTokens, startX + 4 * spacingX, startY, false);
  buildOpenGame(LightTokens, startX + 5 * spacingX, startY, false);
  buildWatch(LightTokens, startX + 6 * spacingX, startY, false);
  buildTeam(LightTokens, startX + 7 * spacingX, startY, false);
  buildActivity(LightTokens, startX + 8 * spacingX, startY, false);

  // Row 2: Dark Theme Screens (9 matching screens)
  buildWelcome(DarkTokens, startX + 0 * spacingX, startY + spacingY, true);
  buildHome(DarkTokens, startX + 1 * spacingX, startY + spacingY, true);
  buildExplore(DarkTokens, startX + 2 * spacingX, startY + spacingY, true);
  buildVenueDetail(DarkTokens, startX + 3 * spacingX, startY + spacingY, true);
  buildBookingReview(DarkTokens, startX + 4 * spacingX, startY + spacingY, true);
  buildOpenGame(DarkTokens, startX + 5 * spacingX, startY + spacingY, true);
  buildWatch(DarkTokens, startX + 6 * spacingX, startY + spacingY, true);
  buildTeam(DarkTokens, startX + 7 * spacingX, startY + spacingY, true);
  buildActivity(DarkTokens, startX + 8 * spacingX, startY + spacingY, true);

  figma.notify("✅ 18 high-fidelity screens with real photos and perfect layout generated!");
  figma.closePlugin();
}

run();
